function createEscrow(
  address borrower,
  address account,
  address asset
) public override returns (address escrowContract) {
  if (!IWildcatArchController(archController).isRegisteredMarket(msg.sender)) {
    revert NotRegisteredMarket();
  }

  escrowContract = getEscrowAddress(borrower, account, asset);

  if (escrowContract.codehash != bytes32(0)) return escrowContract;

  tmpEscrowParams = TmpEscrowParams(borrower, account, asset);

  new WildcatSanctionsEscrow{ salt: keccak256(abi.encode(borrower, account, asset)) }();

  emit NewSanctionsEscrow(borrower, account, asset);

  sanctionOverrides[borrower][escrowContract] = true;

  emit SanctionOverride(borrower, escrowContract);

  _resetTmpEscrowParams();
}

function nukeFromOrbit(address accountAddress) external nonReentrant {
  if (!IWildcatSanctionsSentinel(sentinel).isSanctioned(borrower, accountAddress)) {
    revert BadLaunchCode();
  }
  MarketState memory state = _getUpdatedState();
  _blockAccount(state, accountAddress);
  _writeState(state);
}

function computeControllerAddress(address borrower) external view returns (address) {
  // Salt is borrower address
  bytes32 salt = bytes32(uint256(uint160(borrower)));
  return
    LibStoredInitCode.calculateCreate2Address(ownCreate2Prefix, salt, controllerInitCodeHash);
}

function computeMarketAddress(
  address asset,
  string memory namePrefix,
  string memory symbolPrefix
) external view returns (address) {
  bytes32 salt = _deriveSalt(asset, namePrefix, symbolPrefix);
  return LibStoredInitCode.calculateCreate2Address(ownCreate2Prefix, salt, marketInitCodeHash);
}

function executeWithdrawal(
  address accountAddress,
  uint32 expiry
) external nonReentrant returns (uint256) {
  if (expiry > block.timestamp) {
    revert WithdrawalBatchNotExpired();
  }
  MarketState memory state = _getUpdatedState();

  WithdrawalBatch memory batch = _withdrawalData.batches[expiry];
  AccountWithdrawalStatus storage status = _withdrawalData.accountStatuses[expiry][
    accountAddress
  ];

  uint128 newTotalWithdrawn = uint128(
    MathUtils.mulDiv(batch.normalizedAmountPaid, status.scaledAmount, batch.scaledTotalAmount)
  );

  uint128 normalizedAmountWithdrawn = newTotalWithdrawn - status.normalizedAmountWithdrawn;

  status.normalizedAmountWithdrawn = newTotalWithdrawn;
  state.normalizedUnclaimedWithdrawals -= normalizedAmountWithdrawn;

  if (normalizedAmountWithdrawn == 0) {
    revert NullWithdrawalAmount();
  }

  if (IWildcatSanctionsSentinel(sentinel).isSanctioned(borrower, accountAddress)) {
    _blockAccount(state, accountAddress);
    address escrow = IWildcatSanctionsSentinel(sentinel).createEscrow(
      accountAddress,
      borrower,
      address(asset)
    );
    asset.safeTransfer(escrow, normalizedAmountWithdrawn);
    emit SanctionedAccountWithdrawalSentToEscrow(
      accountAddress,
      escrow,
      expiry,
      normalizedAmountWithdrawn
    );
  } else {
    asset.safeTransfer(accountAddress, normalizedAmountWithdrawn);
  }

  emit WithdrawalExecuted(expiry, accountAddress, normalizedAmountWithdrawn);

  // Update stored state
  _writeState(state);

  return normalizedAmountWithdrawn;
}

function calculateCreate2Address(
  uint256 create2Prefix,
  bytes32 salt,
  uint256 initCodeHash
) internal pure returns (address create2Address) {
  assembly {
    // Cache the free memory pointer so it can be restored
    // at the end
    let ptr := mload(0x40)

    // Write 0xff + address to bytes 11:32
    mstore(0x00, create2Prefix)

    // Write salt to bytes 32:64
    mstore(0x20, salt)

    // Write initcode hash to bytes 64:96
    mstore(0x40, initCodeHash)

    // Calculate create2 hash for token0, token1
    // The EVM only looks at the last 20 bytes, so the dirty
    // bits at the beginning do not need to be cleaned
    create2Address := keccak256(0x0b, 0x55)

    // Restore the free memory pointer
    mstore(0x40, ptr)
  }
}

function deployController() public returns (address controller) {
  if (!archController.isRegisteredBorrower(msg.sender)) {
    revert NotRegisteredBorrower();
  }
  _tmpMarketBorrowerParameter = msg.sender;
  // Salt is borrower address
  bytes32 salt = bytes32(uint256(uint160(msg.sender)));
  controller = LibStoredInitCode.calculateCreate2Address(
    ownCreate2Prefix,
    salt,
    controllerInitCodeHash
  );
  if (controller.codehash != bytes32(0)) {
    revert ControllerAlreadyDeployed();
  }
  LibStoredInitCode.create2WithStoredInitCode(controllerInitCodeStorage, salt);
  _tmpMarketBorrowerParameter = address(1);
  archController.registerController(controller);
  _deployedControllers.add(controller);
}

function getEscrowAddress(
  address borrower,
  address account,
  address asset
) public view override returns (address escrowAddress) {
  return
    address(
      uint160(
        uint256(
          keccak256(
            abi.encodePacked(
              bytes1(0xff),
              address(this),
              keccak256(abi.encode(borrower, account, asset)),
              WildcatSanctionsEscrowInitcodeHash
            )
          )
        )
      )
    );
}

function deployMarket(
  address asset,
  string memory namePrefix,
  string memory symbolPrefix,
  uint128 maxTotalSupply,
  uint16 annualInterestBips,
  uint16 delinquencyFeeBips,
  uint32 withdrawalBatchDuration,
  uint16 reserveRatioBips,
  uint32 delinquencyGracePeriod
) external returns (address market) {
  if (msg.sender == borrower) {
    if (!archController.isRegisteredBorrower(msg.sender)) {
      revert NotRegisteredBorrower();
    }
  } else if (msg.sender != address(controllerFactory)) {
    revert CallerNotBorrowerOrControllerFactory();
  }

  enforceParameterConstraints(
    namePrefix,
    symbolPrefix,
    annualInterestBips,
    delinquencyFeeBips,
    withdrawalBatchDuration,
    reserveRatioBips,
    delinquencyGracePeriod
  );

  TmpMarketParameterStorage memory parameters = TmpMarketParameterStorage({
    asset: asset,
    namePrefix: namePrefix,
    symbolPrefix: symbolPrefix,
    feeRecipient: address(0),
    maxTotalSupply: maxTotalSupply,
    protocolFeeBips: 0,
    annualInterestBips: annualInterestBips,
    delinquencyFeeBips: delinquencyFeeBips,
    withdrawalBatchDuration: withdrawalBatchDuration,
    reserveRatioBips: reserveRatioBips,
    delinquencyGracePeriod: delinquencyGracePeriod
  });

  address originationFeeAsset;
  uint80 originationFeeAmount;
  (
    parameters.feeRecipient,
    originationFeeAsset,
    originationFeeAmount,
    parameters.protocolFeeBips
  ) = controllerFactory.getProtocolFeeConfiguration();

  _tmpMarketParameters = parameters;

  if (originationFeeAsset != address(0)) {
    originationFeeAsset.safeTransferFrom(borrower, parameters.feeRecipient, originationFeeAmount);
  }

  bytes32 salt = _deriveSalt(asset, namePrefix, symbolPrefix);
  market = LibStoredInitCode.calculateCreate2Address(ownCreate2Prefix, salt, marketInitCodeHash);
  if (market.codehash != bytes32(0)) {
    revert MarketAlreadyDeployed();
  }
  LibStoredInitCode.create2WithStoredInitCode(marketInitCodeStorage, salt);

  archController.registerMarket(market);
  _controlledMarkets.add(market);

  _resetTmpMarketParameters();
}

